1	package numeric
2	
3	import (
4		"errors"
5		"strings"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// TestConcurrentCloseAllWaitForShutdown 覆盖同一份归档被多处同时关闭的情形。
12	//
13	// 旧实现里，第一次 Close 把 closed 置位后，后发的 Close 仅凭 closed==true 就
14	// 立即成功返回——此刻 worker 尚未退出，运行中的作业仍在补写中断结果。本测试
15	// 让计算在观察到取消后停在一个由测试控制的“收尾”阶段：若任何一次 Close 在
16	// 该阶段结束前返回，就说明它过早完成。所有 Close 都必须等到 worker 退出、
17	// 运行作业已按“计算被中断”失败落盘后才返回，且每次返回都是可安全重开目录
18	// 的时刻。
19	func TestConcurrentCloseAllWaitForShutdown(t *testing.T) {
20		dir := t.TempDir()
21		s, err := Open(dir)
22		if err != nil {
23			t.Fatalf("open: %v", err)
24		}
25	
26		started := make(chan struct{})
27		finishing := make(chan struct{})
28		release := make(chan struct{})
29		var finishOnce sync.Once
30		s.compute = func(_ uint64, in []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
31			close(started)
32			for !canceled() {
33				time.Sleep(time.Millisecond)
34			}
35			// 已观察到关闭造成的取消，但在测试放行前不返回：模拟计算退出与
36			// worker 裁决落盘之间的窗口。旧对象此刻仍占着计算位置。
37			finishOnce.Do(func() { close(finishing) })
38			<-release
39			return computeResult(in, seed, canceled)
40		}
41	
42		j1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
43		// 排队作业：重复关闭不能启动、失败或取消它。
44		j2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "queued", Values: []int64{10, 20}})
45		<-started
46	
47		const n = 8
48		var wg sync.WaitGroup
49		errCh := make(chan error, n)
50		returned := make(chan struct{}, n)
51		for i := 0; i < n; i++ {
52			wg.Add(1)
53			go func() {
54				defer wg.Done()
55				if err := s.Close(); err != nil {
56					errCh <- err
57					return
58				}
59				returned <- struct{}{}
60			}()
61		}
62	
63		// 等到运行中的计算已观察到取消、但尚未退出。
64		<-finishing
65	
66		// 留出足够时间让全部并发 Close 都进入关闭路径；旧实现下后发调用会在
67		// 这一窗口内立即返回。
68		select {
69		case <-returned:
70			t.Fatal("某次 Close 在运行中作业的中断处理结束前就提前返回")
71		case <-time.After(200 * time.Millisecond):
72		}
73	
74		// 此刻旧对象仍未完成关闭：作业仍是运行态，任何调用方都还不应据此重开。
75		if g, err := s.Get(j1.ID); err != nil || g.Status != StatusRunning {
76			status := "<nil>"
77			if err == nil {
78				status = string(g.Status)
79			}
80			t.Fatalf("关闭收尾期间作业状态=%s err=%v，want running", status, err)
81		}
82	
83		// 放行计算收尾：worker 裁决为“计算被中断”并落盘、退出，所有 Close 随后返回。
84		close(release)
85		done := make(chan struct{})
86		go func() { wg.Wait(); close(done) }()
87		select {
88		case <-done:
89		case <-time.After(5 * time.Second):
90			t.Fatal("并发 Close 互相等待，未能全部结束")
91		}
92		close(errCh)
93		for e := range errCh {
94			t.Errorf("concurrent close: %v", e)
95		}
96		if len(returned) != n {
97			t.Fatalf("应有 %d 次 Close 成功返回，got %d", n, len(returned))
98		}
99	
100		// 任意一次 Close 返回后都可安全重开：运行作业为中断失败、原因可查、
101		// 无成功归档与实际计算输入；排队作业原样保留并继续按序处理。
102		s2, err := Open(dir)
103		if err != nil {
104			t.Fatalf("reopen: %v", err)
105		}
106		defer func() { _ = s2.Close() }()
107	
108		g1, err := s2.Get(j1.ID)
109		if err != nil {
110			t.Fatalf("get j1: %v", err)
111		}
112		if g1.Status != StatusFailed || !strings.Contains(g1.FailureReason, "计算被中断") {
113			t.Fatalf("j1 status=%s reason=%q，want 计算被中断失败", g1.Status, g1.FailureReason)
114		}
115		if g1.Archive != nil || len(g1.EffectiveValues) != 0 {
116			t.Fatalf("中断失败不应留下成功归档或实际输入，got archive=%v effective=%v",
117				g1.Archive, g1.EffectiveValues)
118		}
119	
120		g2 := waitStatus(t, s2, j2.ID, StatusSucceeded)
121		if g2.Archive == nil || g2.Archive.Sum != 30 {
122			t.Fatalf("排队作业重开后应正常成功（总和 30），got status=%s", g2.Status)
123		}
124	}
125	
126	// TestConcurrentCloseIdleStore 没有运行中作业的空闲归档被并发关闭：每次调用
127	// 都正常返回、互不卡死；完全关闭后的再次 Close 立即成功。
128	func TestConcurrentCloseIdleStore(t *testing.T) {
129		s, _ := openTestStore(t)
130	
131		const n = 8
132		var wg sync.WaitGroup
133		for i := 0; i < n; i++ {
134			wg.Add(1)
135			go func() {
136				defer wg.Done()
137				if err := s.Close(); err != nil {
138					t.Errorf("idle close: %v", err)
139				}
140			}()
141		}
142		wg.Wait()
143	
144		if err := s.Close(); err != nil {
145			t.Fatalf("close after fully closed: %v", err)
146		}
147		if _, err := s.Submit(SubmitRequest{Submitter: "a", Values: []int64{1}}); !errors.Is(err, ErrStoreClosed) {
148			t.Fatalf("submit after close: %v", err)
149		}
150	}
