// 第二个停止信号尚未置位”的历史瞬间，并让计算在此刻返回成功数值：worker 仍
// 必须把运行作业判为中断失败，且不得启动后面的排队作业。
func TestCloseSingleGateWorkerHonorsClosed(t *testing.T) {
	s, _ := openTestStore(t)

	entered := make(chan struct{}, 1)
	release := make(chan struct{})
	s.compute = func(id uint64, in []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
		entered <- struct{}{}
		<-release
		return 3, 5, "", true // 无视中止，返回一份本可成功的数值
	}

	run := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1, 2}})
	queued := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{9}})
	<-entered

	// 仅进入“关闭已开始拒绝提交”这一半：closed 置位，但刻意不关闭 stopCh，
	// 忠实复现旧实现解锁后、停止信号置位前的窗口（新代码的真实 Close 永远
	// 会在同一临界区把两者一起置位，生产中不存在该中间态）。
	s.mu.Lock()
	s.closed = true
	s.mu.Unlock()

	close(release)
	// worker 裁决完运行作业后，下一轮循环在同一 closed 位前退出；Wait 返回即
	// 说明它既没有补写成功，也没有启动排队作业。
