	if gq.Status != StatusQueued || !gq.StartedAt.IsZero() || gq.Archive != nil {
		t.Fatalf("关闭生效后不得从队列启动新作业：status=%s started=%v archive=%v",
			gq.Status, gq.StartedAt, gq.Archive)
	}
}

